function ordBatches(){var left=Math.round(mgNeed()/1000*1000)/1000,out=[],i=0;var g=mgNeed()/1000;while(g>0.0005){var b=Math.min(GPB,g);out.push(['B-'+(414+i),ORD.first+i,ORD.prod,b]);g-=b;i++;}return out;}
